const $=id=>document.getElementById(id);const API_REQUEST_TIMEOUT_MS=12000;
async function fetchWithTimeout(url,options={},timeoutMs=API_REQUEST_TIMEOUT_MS){
 const controller=new AbortController();
 const timer=window.setTimeout(()=>controller.abort(),timeoutMs);
 try{return await fetch(url,{...options,signal:controller.signal});}
 catch(error){if(error&&error.name==='AbortError')throw new Error('API request timed out after '+Math.round(timeoutMs/1000)+' seconds');throw error;}
 finally{window.clearTimeout(timer);}
}
const MAX_CANDLE_AGE_SECONDS=Object.freeze({"1m":120,"15m":1080,"1h":3780,"4h":14580});let bars=[];let chart=null,candleSeries=null;
if(window.LightweightCharts){chart=LightweightCharts.createChart($('chart'),{width:$('chart').clientWidth,height:$('chart').clientHeight,layout:{background:{type:'solid',color:'#121c2c'},textColor:'#91a2ba'},grid:{vertLines:{color:'#27364b'},horzLines:{color:'#27364b'}},rightPriceScale:{borderColor:'#27364b'},timeScale:{borderColor:'#27364b',timeVisible:true,secondsVisible:false},localization:{locale:'en-US'},crosshair:{vertLine:{color:'#526783'},horzLine:{color:'#526783'}}});candleSeries=chart.addSeries(LightweightCharts.CandlestickSeries,{upColor:'#36c98f',downColor:'#f16b75',borderVisible:false,wickUpColor:'#36c98f',wickDownColor:'#f16b75'});}
window.addEventListener('resize',()=>{if(chart){const el=$('chart');chart.resize(Math.max(1,el.clientWidth),Math.max(1,el.clientHeight));}});
function draw(){if(!candleSeries){$('message').textContent='FAIL CLOSED · chart library did not load; check network/CDN policy';return}candleSeries.setData(bars.map(b=>({time:Math.floor(b.open_time/1000),open:Number(b.open),high:Number(b.high),low:Number(b.low),close:Number(b.close)})));if(bars.length)chart.timeScale().fitContent()}
function updateIndicators(j){
 const ids=['indicatorEma','indicatorVwap','indicatorAtr','indicatorVolatility','indicatorVolumeRatio','indicatorRegime'];
 const i=j?.indicators;
 const valid=!!i&&i.status==='READY'&&i.source==='gateio_public_spot'&&i.source_reader==='global_market_data_reader_v1'&&i.symbol===j.symbol&&i.interval===j.interval&&i.input_batch_sha256===j.input_batch_sha256&&i.feature_batch_sha256===j.input_batch_sha256&&i.quality_passed===true&&i.execution_enabled===false&&i.orders_placed===false;
 if(!valid){ids.forEach(id=>$(id).textContent='—');$('indicatorStatus').textContent='GATED · '+(i?.reason||'INDICATOR_EVIDENCE_UNAVAILABLE')+' · no stale or mismatched values shown';return;}
 const finite=v=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v));
 const number=(v,d=2)=>finite(v)?Number(v).toLocaleString(undefined,{maximumFractionDigits:d}):'—';
 $('indicatorEma').textContent=number(i.ema,4);
 $('indicatorVwap').textContent=number(i.vwap,4);
 $('indicatorAtr').textContent=number(i.average_true_range,4);
 $('indicatorVolatility').textContent=finite(i.realized_volatility)?(Number(i.realized_volatility)*100).toFixed(2)+'%':'—';
 $('indicatorVolumeRatio').textContent=finite(i.volume_ratio)?Number(i.volume_ratio).toFixed(2)+'×':'—';
 $('indicatorRegime').textContent=String(i.regime||'UNKNOWN').toUpperCase();
 $('indicatorStatus').textContent='READY · EMA'+i.ema_period+' / VWAP'+i.vwap_period+' · same validated '+i.interval+' batch · SHA-256 '+i.input_batch_sha256.slice(0,16)+'… · descriptive only';
}
async function refresh(){const btn=$('refresh');btn.disabled=true;$('message').textContent='Fetching and validating closed reference candles…';try{const q=new URLSearchParams({symbol:$('symbol').value,interval:$('interval').value}),r=await fetchWithTimeout('/api/candles?'+q,{cache:'no-store'}),j=await r.json();if(!r.ok)throw Error(j.reason_code||j.error||'Market data unavailable');if(j.status!=='ok')throw Error(j.status==='gaps_present'?'Persisted candle gaps detected':'Market data status is not OK');if(j.source!=='gateio_public_spot'||j.source_reader!=='global_market_data_reader_v1'||j.venue!=='gateio'||j.product!=='spot'||j.symbol!=='BTCUSDT'||j.source_symbol!=='BTC_USDT'||j.symbol_mapping_verified!==true||typeof j.input_batch_sha256!=='string'||!/^[a-f0-9]{64}$/.test(j.input_batch_sha256))throw Error('Canonical Gate.io candle provenance is not verified');if(j.execution_enabled!==false||j.orders_placed!==false)throw Error('Read-only dashboard safety contract violated');if(!Array.isArray(j.gaps)||j.gaps.length!==0)throw Error('Persisted candle gaps detected');const maxAgeSeconds=MAX_CANDLE_AGE_SECONDS[$('interval').value];if(j.interval!==$('interval').value)throw Error('Candle interval mismatch');if(!Number.isFinite(j.latest_age_seconds)||!Number.isFinite(maxAgeSeconds)||j.latest_age_seconds<0||j.latest_age_seconds>maxAgeSeconds)throw Error('Stale candle batch: '+(Number.isFinite(j.latest_age_seconds)?j.latest_age_seconds.toFixed(1):'unknown')+'s > '+maxAgeSeconds+'s');if(!Array.isArray(j.candles)||!j.candles.length)throw Error('No closed candles returned');bars=j.candles;updateIndicators(j);const b=bars[bars.length-1];$('price').textContent=Number(b.close).toLocaleString(undefined,{maximumFractionDigits:8});$('stamp').textContent=new Date(b.close_time).toISOString().replace('T',' ').replace('.000Z',' UTC');$('volume').textContent=b.volume;$('count').textContent=String(bars.length);$('source').textContent='Source: '+j.source+' · '+j.product+' · '+j.symbol;$('message').textContent='VALIDATED · '+(j.feature_ready?'FEATURES READY':'FEATURES GATED: '+j.feature_reason)+' · stream '+j.stream_status+(j.stream_reason?' ('+j.stream_reason+')':'')+' · latest age '+j.latest_age_seconds.toFixed(1)+'s · volume unchanged';draw()}catch(e){bars=[];updateIndicators(null);draw();['price','stamp','volume','count'].forEach(k=>$(k).textContent='—');$('message').textContent='FAIL CLOSED · '+e.message}finally{btn.disabled=false}}
async function refreshJournal(){const status=$('journalStatus'),rows=$('journalRows');status.textContent='Verifying immutable decision journal…';rows.replaceChildren();try{const r=await fetchWithTimeout('/api/journal?limit=50',{cache:'no-store'}),j=await r.json();if(!r.ok)throw Error(j.error||'Journal unavailable');if(j.status==='NOT_CONFIGURED'){status.textContent='NOT CONFIGURED · Set HES_FORWARD_LEARNING_DECISION_JOURNAL to an explicit durable path. No entries are invented.';return}if(j.status==='EMPTY'){status.textContent='VERIFIED · Journal is empty.';return}status.textContent='VERIFIED · '+String(j.decision_count??j.events.length)+' decision events / '+String(j.count)+' total journal records'+(j.truncated?' (showing newest 50)':'')+' · execution OFF · outcomes not inferred';for(const e of j.events){const tr=document.createElement('tr');const family=e.strategy_family_id?(e.strategy_family_id+' · '+(e.strategy_family_activation_state||'state unknown')):'—';for(const value of [e.observed_at.replace('T',' ').replace('+00:00',' UTC'),e.symbol+' / '+e.timeframe,e.decision,family,e.rejected_at+(e.reason_codes.length?': '+e.reason_codes.join(', '):''),e.realized_outcome,e.event_sha256.slice(0,12)+'…']){const td=document.createElement('td');td.textContent=value;tr.appendChild(td)}rows.appendChild(tr)}}catch(e){status.textContent='FAIL CLOSED · '+e.message+' · no journal rows shown';rows.replaceChildren()}}
$('refresh').addEventListener('click',refresh);$('symbol').addEventListener('change',refresh);$('interval').addEventListener('change',refresh);$('journalRefresh').addEventListener('click',refreshJournal);refresh();refreshJournal();setInterval(refresh,15000);setInterval(refreshJournal,30000);


async function refreshStrategyV2(){const status=$('v2Status');try{const r=await fetchWithTimeout('/api/strategy-v2',{cache:'no-store'});const j=await r.json();if(!r.ok)throw Error(j.reason||'Canonical V2 report unavailable');$('v2Decision').textContent=j.decision||'NO_TRADE';status.textContent=j.status||'BLOCKED';$('v2Regime').textContent=j.market_regime||'UNKNOWN';$('v2Version').textContent=j.agent_version||'—';$('v2Outcomes').textContent=String(j.wins??0)+' W / '+String(j.losses??0)+' L / '+String(j.timeouts??0)+' T';$('v2Journal').textContent=String(j.journal?.decision_count??0)+' decisions';const reasons=[...(j.latest_gate_evidence?.confirmation?.reason_codes||[]),...(j.latest_gate_evidence?.risk?.reason_codes||[])];$('v2Reasons').textContent=reasons.join(' · ')||'No gate reason codes supplied';$('v2Evidence').textContent='Gate.io public Spot BTC_USDT · market evidence age '+Number(j.market_evidence_age_seconds||0).toFixed(0)+'s · report age '+Number(j.report_age_seconds||0).toFixed(0)+'s · SHA-256 '+String(j.report_sha256||'').slice(0,16)+'… · execution OFF';}catch(e){$('v2Decision').textContent='NO_TRADE';status.textContent='BLOCKED';$('v2Regime').textContent='UNKNOWN';$('v2Version').textContent='—';$('v2Outcomes').textContent='—';$('v2Journal').textContent='—';$('v2Reasons').textContent='FAIL CLOSED · '+e.message;$('v2Evidence').textContent='Canonical V2 evidence is unavailable or invalid. No stale values or alternate strategy are substituted; execution remains disabled.'}}
$('refresh').addEventListener('click',refreshStrategyV2);refreshStrategyV2();setInterval(refreshStrategyV2,15000);

async function refreshMother(){const status=$('motherStatus'),witness=$('motherWitness'),trace=$('motherTrace'),reasons=$('motherReasons'),stages=$('motherStages');try{const r=await fetchWithTimeout('/api/mother',{cache:'no-store'}),j=await r.json();if(!r.ok)throw Error((j.reason_codes||[]).join(' · ')||j.status||'Mother live runtime unavailable');status.textContent=j.status||'UNKNOWN';witness.textContent=j.witness?.verified?'VERIFIED':'NOT VERIFIED';trace.textContent=String(j.trace_id||'—').slice(0,16)+'… / '+String(j.audit_sha256||'').slice(0,12)+'…';reasons.textContent=(j.reason_codes||[]).join(' · ')||'All observation stages completed; execution remains unauthorized.';stages.replaceChildren();const executed=new Map((j.stages||[]).map(s=>[s.agent,s]));for(const item of (j.registered_specialists||[])){const name=typeof item==='string'?item:item.name;const s=executed.get(name);const li=document.createElement('li');li.textContent=name+' · '+(s?(s.state+(s.reason_codes?.length?' · '+s.reason_codes.join(', '):'')):'WIRED · WAITING FOR UPSTREAM GATE');stages.appendChild(li)}if(!stages.children.length){const li=document.createElement('li');li.textContent='No verified runtime specialists.';stages.appendChild(li)}$('motherEvidence').textContent='Live snapshot '+String(j.snapshot_sha256||'').slice(0,16)+' · '+String(j.executed_count??(j.stages||[]).length)+' / '+String(j.registered_count??7)+' specialists executed · Gate.io Public Spot BTC_USDT · witness '+(j.witness?.verified?'verified':'not verified')+' · candle-time continuity only · trade.sequence unused · consensus '+String(j.consensus?.decision||'NO_TRADE')+'/'+String(j.consensus?.conflict_class||'UNVERIFIED')+' · consensus SHA '+String(j.consensus?.audit_sha256||'').slice(0,12)+'… · execution OFF · outcomes not inferred';const pg=j.paper_execution_gate||{};$('motherPaperGate').textContent='Paper simulation gate: '+String(pg.status||'BLOCKED')+' · '+(pg.reason_codes||[]).join(' · ');}catch(e){status.textContent='BLOCKED';witness.textContent='NOT VERIFIED';trace.textContent='—';reasons.textContent='FAIL CLOSED · '+e.message;stages.replaceChildren();const li=document.createElement('li');li.textContent='No verified runtime stages; no stale values substituted.';stages.appendChild(li);$('motherEvidence').textContent='The live Mother runtime could not verify the current Gate.io data and specialist chain. Execution remains disabled.';$('motherPaperGate').textContent='Paper simulation gate: BLOCKED · live evidence unavailable.'}}
refreshMother();setInterval(refreshMother,15000);


(()=>{
 const loginForm=$('motherChatLoginForm'),chatForm=$('motherChatForm');
 if(!loginForm||!chatForm)return;
 const loginBox=$('motherChatLogin'),workspace=$('motherChatWorkspace');
 const messages=$('motherChatMessages'),loginStatus=$('motherChatLoginStatus');
 function bubble(role,text,status){
  const article=document.createElement('article');article.className='mother-chat-message '+role;
  const heading=document.createElement('strong');heading.textContent=role==='user'?'You':'Mother · '+(status||'EVIDENCE');
  const body=document.createElement('p');body.textContent=String(text||'');
  article.append(heading,body);messages.appendChild(article);messages.scrollTop=messages.scrollHeight;
 }
 function evidenceDetails(result){
  const rows=[...(result.claims||[]).map(x=>(x.label||'Evidence')+': '+String(x.value)),...(result.uncertainties||[]).map(x=>'Uncertainty: '+x),...(result.evidence_refs||[]).map(x=>'Evidence ref: '+x)];
  if(!rows.length)return;
  const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Evidence and limitations';details.appendChild(summary);
  const list=document.createElement('ul');for(const row of rows){const li=document.createElement('li');li.textContent=row;list.appendChild(li)}details.appendChild(list);messages.appendChild(details);messages.scrollTop=messages.scrollHeight;
 }
 function showLogin(message){
  workspace.hidden=true;loginBox.hidden=false;
  if(message)loginStatus.textContent=message;
 }
 function showWorkspace(){
  loginBox.hidden=true;workspace.hidden=false;
  messages.replaceChildren();bubble('mother','Command Center unlocked. Ask about status, a recorded decision, market context, journal, news or diagnostics. No external model is used.','READY');
  $('motherChatInput').focus();
 }
 loginForm.addEventListener('submit',async event=>{
  event.preventDefault();const token=$('motherChatToken').value;const button=$('motherChatUnlock');button.disabled=true;loginStatus.textContent='Checking local access…';
  try{
   const response=await fetchWithTimeout('/api/mother-chat/session',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({token})},60000);
   const result=await response.json();$('motherChatToken').value='';
   if(!response.ok)throw Error(result.error||'CHAT_AUTHENTICATION_FAILED');
   showWorkspace();
  }catch(error){$('motherChatToken').value='';loginStatus.textContent='Access not granted · '+error.message;}
  finally{button.disabled=false;}
 });
 chatForm.addEventListener('submit',async event=>{
  event.preventDefault();const input=$('motherChatInput'),message=input.value.trim();if(!message)return;
  const button=$('motherChatSend');button.disabled=true;input.value='';bubble('user',message);
  try{
   const response=await fetchWithTimeout('/api/mother-chat',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({message})},60000);
   const result=await response.json();
   if(response.status===401){showLogin('Session expired. Unlock the Command Center again.');bubble('mother','Session expired; no request was processed.','BLOCKED');return;}
   if(!response.ok)throw Error(result.error||'CHAT_REQUEST_FAILED');
   bubble('mother',result.answer||'No answer was returned.',result.status||'UNKNOWN');evidenceDetails(result);
  }catch(error){bubble('mother','Request blocked · '+error.message,'BLOCKED');}
  finally{button.disabled=false;}
 });
 $('motherChatLogout').addEventListener('click',async()=>{
  try{await fetchWithTimeout('/api/mother-chat/logout',{method:'POST',credentials:'same-origin'},5000);}catch(_){}
  showLogin('Command Center locked.');messages.replaceChildren();
 });
})(); 

function renderNewsItems(items){
 const list=$('newsItems');if(!list)return;list.replaceChildren();
 const locale=window.HESDashboardLocale?.get?.()||document.documentElement.lang||'en';
 const unavailable={fa:'تفسیر در دسترس نیست؛ شواهد کافی یا معتبر وجود ندارد.',en:'Interpretation unavailable; evidence is insufficient or invalid.',de:'Einordnung nicht verfügbar; Belege sind unzureichend oder ungültig.',fr:'Interprétation indisponible ; les éléments sont insuffisants ou invalides.'};
 const noItems={fa:'در تصویر فعلی، تیتر تأییدشده و مرتبطی وجود ندارد.',en:'No sufficiently relevant, verified headlines in the current snapshot.',de:'Im aktuellen Snapshot gibt es keine ausreichend relevanten, verifizierten Schlagzeilen.',fr:'Aucun titre vérifié suffisamment pertinent dans l’instantané actuel.'};
 const fields=['what_happened','why_it_matters','affected_market','relevance_scope','potential_effect','transmission_channel','time_horizon','what_to_monitor','educational_concept','uncertainty'];
 for(const item of (Array.isArray(items)?items:[]).slice(0,5)){
  const li=document.createElement('li');
  const headline=document.createElement('p');
  headline.textContent=(item.title||'Untitled')+' · '+(item.source||'Unknown source')+' · '+(item.published_at||'Publication time unverified')+' · impact '+String(item.impact??'—');
  li.appendChild(headline);
  const interpretation=item.interpretation;
  const localized=interpretation&&interpretation.schema_version==='hes.news_item_interpretation.v1'&&interpretation.localized&&interpretation.localized[locale];
  const details=document.createElement('details');details.className='news-interpretation';details.setAttribute('data-no-translate','true');
  const summary=document.createElement('summary');summary.textContent=localized?.labels?.title||({fa:'تفسیر هوش مصنوعی و آموزش اقتصادی',en:'AI interpretation & economic learning',de:'KI-Einordnung & Wirtschaftswissen',fr:'Interprétation IA et pédagogie économique'}[locale]||'AI interpretation & economic learning');details.appendChild(summary);
  if(!localized){const p=document.createElement('p');p.textContent=unavailable[locale]||unavailable.en;details.appendChild(p);}
  else{
   for(const key of fields){const value=localized[key];if(typeof value!=='string'||!value.trim())continue;
    const row=document.createElement('div');row.className='news-interpretation-row';
    const label=document.createElement('strong');label.textContent=localized.labels[key==='what_happened'?'what':key==='why_it_matters'?'why':key==='affected_market'?'market':key==='relevance_scope'?'scope':key==='potential_effect'?'effect':key==='transmission_channel'?'channel':key==='time_horizon'?'horizon':key==='what_to_monitor'?'monitor':key==='educational_concept'?'education':key==='uncertainty'?'uncertainty':'market']||key;
    const text=document.createElement('p');text.textContent=value;row.append(label,text);details.appendChild(row);
   }
   const disclaimer=document.createElement('p');disclaimer.className='muted';disclaimer.textContent=localized.disclaimer||'';details.appendChild(disclaimer);
  }
  li.appendChild(details);list.appendChild(li);
 }
 if(!list.children.length){const li=document.createElement('li');li.textContent=noItems[locale]||noItems.en;list.appendChild(li);}
}
async function refreshNewsMonitor(){try{const r=await fetchWithTimeout('/api/news',{cache:'no-store'}),j=await r.json();if(!r.ok)throw Error(j.error||'News monitor unavailable');const m=j.monitor||{},b=j.brief||{},p=b.provenance||{},h=m.source_health||p.source_health||[];const count=s=>h.filter(x=>x.status===s).length,scope=s=>h.filter(x=>x.source_scope===s).length,freshness=s=>h.filter(x=>x.freshness_status===s).length;$('newsStatus').textContent=m.status||'UNKNOWN';$('newsCoverage').textContent=m.source_profile_status||'UNKNOWN';$('newsSources').textContent=count('ok')+' / '+count('ok_empty')+' / '+count('failed');$('newsScopes').textContent=scope('international')+' / '+scope('domestic')+' / '+scope('venue');$('newsFreshness').textContent=freshness('fresh')+' / '+freshness('aging')+' / '+freshness('stale')+' / '+freshness('future')+' / '+freshness('empty')+' / '+freshness('failed')+' / '+freshness('unknown');$('newsLastPoll').textContent=m.last_poll_at||'—';$('newsSummary').textContent=(b.headline||'No headline')+' · '+(b.mother_agent_summary||'');$('newsFlags').textContent=(b.veto_flags||[]).join(' · ')||'No explicit news flags; context only. '+(m.last_error||'');const sourceList=$('newsSourceDetails');sourceList.replaceChildren();for(const source of h){const li=document.createElement('li');const age=source.newest_age_minutes==null?'age unknown':Math.round(source.newest_age_minutes/60)+'h old';li.textContent=(source.source_id||'unknown-source')+' · '+(source.source_scope||'scope unknown')+' · transport '+(source.status||'unknown')+' · freshness '+(source.freshness_status||'not available')+' · '+(source.newest_published_at||'no publication timestamp')+' · '+age;sourceList.appendChild(li)}if(!sourceList.children.length){const li=document.createElement('li');li.textContent='No per-source health loaded.';sourceList.appendChild(li)}window.__hesNewsFindings=Array.isArray(b.findings)?b.findings:[];renderNewsItems(window.__hesNewsFindings);}catch(e){$('newsStatus').textContent='BLOCKED';$('newsCoverage').textContent='UNKNOWN';$('newsSources').textContent='—';$('newsScopes').textContent='—';$('newsFreshness').textContent='—';$('newsLastPoll').textContent='—';$('newsSummary').textContent='FAIL CLOSED · '+e.message;$('newsFlags').textContent='No fresh verified news snapshot; no directional inference or execution.';const sourceList=$('newsSourceDetails');sourceList.replaceChildren();const sourceError=document.createElement('li');sourceError.textContent='Per-source freshness unavailable.';sourceList.appendChild(sourceError);const list=$('newsItems');list.replaceChildren();const li=document.createElement('li');li.textContent='News evidence unavailable or stale.';list.appendChild(li)}}
refreshNewsMonitor();setInterval(refreshNewsMonitor,30000);

function precisionEntryFailureMessage(payload){
 const codes=Array.isArray(payload?.reason_codes)?payload.reason_codes.filter(code=>typeof code==='string'&&code.trim()):[];
 const locale=document.documentElement.lang||'en';
 const messages={
  en:'Multi-timeframe evidence unavailable. Precision Entry remains blocked.',
  fa:'شواهد چندبازه‌ای در دسترس نیست؛ ورود دقیق مسدود می‌ماند.',
  de:'Multi-Timeframe-Nachweise nicht verfügbar. Der Präzisionseinstieg bleibt blockiert.',
  fr:'Preuves multi-unités indisponibles. L’entrée précise reste bloquée.'
 };
 const fallback=payload?.reason&&payload.reason!=='ValueError'?String(payload.reason):'';
 return (messages[locale]||messages.en)+(codes.length?' · '+codes.join(' · '):fallback?' · '+fallback:'');
}

async function refreshPrecisionEntry(){
 const ids={"4h":"pe4h","1h":"pe1h","15m":"pe15m","1m":"pe1m"};
 try{
  const r=await fetchWithTimeout('/api/precision-entry',{cache:'no-store'}),v=await r.json();
  if(!r.ok)throw Error(precisionEntryFailureMessage(v));
  for(const [tf,id] of Object.entries(ids))$(id).textContent=(v.timeframes?.[tf]?.status||'BLOCKED')+' · '+String(v.timeframes?.[tf]?.closed_candles??0)+' bars';
  $('pe15m').textContent=(v.setup_decision||'NO_TRADE')+' / '+(v.confirmation_state||'UNKNOWN');
  $('pe1m').textContent=(v.timeframes?.['1m']?.status||'BLOCKED')+' · '+String(v.timeframes?.['1m']?.closed_candles??0)+' bars';
  $('peState').textContent=v.entry_state||'BLOCKED';
  $('peRisk').textContent=v.risk_gate_state||'UNVERIFIED';
  $('peReasons').textContent=(v.reason_codes||[]).join(' · ')+' · '+v.authority+' · execution OFF';
 }catch(e){
  for(const id of Object.values(ids))$(id).textContent='BLOCKED';
  $('pe15m').textContent='NO_TRADE';$('pe1m').textContent='BLOCKED';
  $('peState').textContent='BLOCKED';$('peRisk').textContent='UNVERIFIED';
  $('peReasons').textContent='FAIL CLOSED · '+e.message+' · execution OFF';
 }
}
refreshPrecisionEntry();setInterval(refreshPrecisionEntry,15000);



